<?php require 'header.php'; $db=db_load(); $page_title='Appointments'; ?><div class="admin-top"><h1>Appointments</h1><div class="list-toolbar"><div class="list-search"><input type="search" id="appointmentSearch" placeholder="Search appointments..." autocomplete="off" aria-label="Search appointments"></div><a class="btn" href="calendar.php">Open Calendar</a></div></div><div class="table-wrap"><table id="appointmentsTable"><tr><th>Appointment No</th><th>Patient No</th><th>Patient</th><th>Date</th><th>Time</th><th>Status</th><th>Amount</th><th>Action</th></tr><?php foreach(array_reverse($db['appointments']) as $a): $p=find_item($db['patients'],$a['patient_id']); ?><tr class="appointment-row" data-search="<?=e(strtolower(($a['number']??'').' '.($p['number']??'').' '.($p['name']??'').' '.($a['date']??'').' '.($a['time']??'').' '.($a['status']??'')))?>"><td><?=e($a['number'])?></td><td><?=e($p['number']??'-')?></td><td><?=e($p['name']??'-')?></td><td><?=e(date_fmt($a['date']))?></td><td><?=e($a['time'])?></td><td><span class="badge"><?=e($a['status'])?></span></td><td>₹<?=number_format((float)$a['amount'],2)?></td><td><a class="btn btn-sm" href="appointment-edit.php?id=<?=e($a['id'])?>">Open</a></td></tr><?php endforeach; ?><tr id="noAppointmentsFound" style="display:none"><td colspan="8" style="text-align:center;padding:30px">No appointments found.</td></tr></table></div><script>(function(){const search=document.getElementById('appointmentSearch');const rows=Array.from(document.querySelectorAll('.appointment-row'));const empty=document.getElementById('noAppointmentsFound');if(!search)return;search.addEventListener('input',function(){const query=this.value.trim().toLowerCase();let visible=0;rows.forEach(function(row){const match=!query||row.dataset.search.includes(query);row.style.display=match?'':'none';if(match)visible++;});empty.style.display=visible?'none':'';});})();</script><?php require 'footer.php'; ?>
